import { loadConfig } from "./src/config.ts";

const envText = `PORT=8080
HOST=0.0.0.0
APP_NAME="Order Service"
DEBUG=false
MOTD='hello # not a comment'`;

const cfg = loadConfig(envText);
console.log("Config loaded:");
console.log("  port:", cfg.port);
console.log("  host:", cfg.host);
console.log("  appName:", cfg.appName);
console.log("  debug:", cfg.debug);
console.log("  motd:", cfg.motd);

// Verify values are correct
console.log("\nVerification:");
console.log("  appName has spaces:", cfg.appName === "Order Service" ? "✓" : "✗");
console.log("  motd has # inside quotes:", cfg.motd === "hello # not a comment" ? "✓" : "✗");
EOF
